EVAL={
'psychiatric-medication-management':['The symptoms and everyday activities you want treatment to improve','Previous medication trials, benefits, side effects, and current prescriptions','Sleep, medical conditions, supplements, substance use, and therapy','Your preferences, questions, and treatment goals'],
'adhd-treatment-utah':['Developmental history and how concerns affect more than one setting','Attention, organization, task initiation, impulsivity, and daily functioning','Sleep, mood, anxiety, substance use, medical factors, and alternative explanations','Prior treatment response, tolerability, and practical behavioral or environmental supports'],
'anxiety-depression-treatment':['Symptom patterns, severity, safety, and effects on everyday life','Sleep, energy, medical contributors, and substance use','Previous medication response and current therapy','Your goals and what meaningful improvement would look like'],
'womens-mental-health':['Mood, anxiety, attention, and symptoms across life-stage transitions','Current treatment and medication questions around pregnancy or postpartum when appropriate','Individual benefits, risks, preferences, and medical context','Coordination with an OB/GYN, primary-care provider, or therapist when authorized'],
'addiction-recovery':['Recovery goals, current treatment, and substance-use patterns','Co-occurring ADHD, anxiety, depression, trauma, sleep, or mood concerns','Medication safety, prior response, and continuity after treatment or discharge','Coordination with treatment and recovery teams with your consent'],
 'trauma-ptsd':['The symptoms you want help with, at a pace that respects your comfort','Sleep, mood, anxiety, daily functioning, and current supports','Prior treatments and medication benefits or difficulties','Your therapy relationship and opportunities to coordinate care when authorized'],
'integrative-psychiatry':['Current psychiatric treatment, symptoms, and daily functioning','Sleep, nutrition, movement, medical conditions, and relevant lifestyle factors','Supplements, medications, possible interactions, and product quality','Evidence strength, uncertainty, and whether an adjunct fits your goals']}
APPROACH={
'womens-mental-health':'Our current service is psychiatric evaluation and medication management. Decisions are individualized rather than based on one-size-fits-all medication claims. With your authorization, care can be coordinated with your OB/GYN, primary-care provider, or therapist.',
'addiction-recovery':'Ischys offers outpatient psychiatric continuity for people in recovery and those with co-occurring mental health needs. Care may include medication for opioid use disorder when clinically appropriate, alongside coordination with your treatment or recovery team with consent. This is not a residential treatment or emergency service.',
 'trauma-ptsd':'Medication management may address specific symptoms or co-occurring conditions while respecting the role of evidence-based psychotherapy. Medication does not erase trauma. With your permission, we can coordinate with your therapist as part of your broader care.',
'integrative-psychiatry':'Integrative psychiatry adds clinically relevant context to evidence-based psychiatric care. It does not replace standard treatment. When discussing supplements or other adjuncts, we consider evidence, uncertainty, possible interactions, medical conditions, and product quality. Natural does not automatically mean safe or effective.'}
for s in SERVICES[:7]:
 slug=s['slug']; related=[x for x in ARTICLES if slug in x['services']]
 intro=s['audience'].replace('Who it is for: ','')
 body=hero(s['h1'],intro,s['title'])
 body+='<section class="section"><div class="wrap service-layout"><div class="service-body"><section><h2>When you might seek care</h2><p>'+esc(intro)+'</p><p>You do not need to have all the answers before your first visit. Bring the concerns that are affecting your life and the questions you want to discuss.</p></section><section><h2>What your evaluation considers</h2><ul>'+''.join('<li>'+esc(x)+'</li>' for x in EVAL[slug])+'</ul></section><section><h2>A thoughtful approach to treatment</h2><p>'+esc(APPROACH.get(slug,s['approach']))+'</p></section><section><h2>How medication management works</h2><p>We identify the symptoms and functional goals that matter to you, review your prior response and side effects, and discuss the potential benefits and risks of treatment options. Decisions are made together.</p><p>Follow-up appointments are a chance to review what has changed, how you are functioning, and whether the plan needs adjustment. Sleep, medical factors, substances, lifestyle, and therapy remain part of that conversation.</p><div class="callout"><p>'+MEDICATION+'</p></div></section><section><h2>Care without the rushed medication visit</h2><p>Laura’s approach looks at the whole person: what you have tried, what has helped, what has not, and what matters in your everyday life. You have a voice in your treatment.</p>'+framework()+a('/first-visit/','What to expect at your first visit →','text-link')+'</section><section><h2>Common questions</h2>'+faq([('Can I meet through telehealth?','Ischys provides in-person care in American Fork and telehealth throughout Utah. Contact the practice to discuss which appointment format fits your needs.'),('Does an evaluation guarantee a prescription?','No. Medication decisions are individualized and depend on clinical appropriateness, safety, and prescribing requirements.'),('Can you work with my therapist?','With your authorization, Laura can coordinate relevant care with your therapist or other treating professionals. Psychiatric medication management supports your existing treatment relationship.'),('What is the free consultation?',CONSULT),('Can I use insurance?',INSURANCE_COPY)])+'</section>'+credit()+'</div><aside class="aside-card"><h2>Plan your visit</h2><p>In person in American Fork<br>Telehealth throughout Utah</p><p>'+esc(C['address'])+'</p>'+ctas()+'<p>'+CONSULT+'</p><hr><p>'+INSURANCE_COPY+'</p>'+a('/fees-insurance/','View insurance details →','text-link')+'</aside></div></section><section class="soft section"><div class="wrap"><h2>Learn more at your own pace.</h2>'+article_cards(related)+'</div></section>'+end_cta()
 write('/'+slug+'/',s['h1'],short[SERVICES.index(s)]+' In-person care in American Fork and Utah telehealth.',body,'MedicalWebPage')
# First visit
body=hero('What to Expect at Your First Psychiatric Visit at Ischys','A clear starting point for new patients and families. Your first evaluation is a 60-minute conversation about your concerns, history, and goals.','Your first visit')
body+='<section class="section"><div class="wrap two-col"><div><h2>Before your appointment</h2><ul><li>Gather your medication and supplement list, including doses and prior medication trials.</li><li>Think about current symptoms, sleep, medical history, substance use, and daily functioning.</li><li>Write down questions and what you hope treatment will help you do or enjoy.</li><li>Complete any requested intake forms through the secure patient portal.</li></ul><div class="callout"><p>'+RECORDS+'</p></div>'+a('/portal/','Open the patient portal →','text-link','portal_click')+'</div><div><h2>During your evaluation</h2><p>Laura will review your history and prior treatment, current concerns, medications and supplements, medical and sleep factors, and your goals. There is time to ask questions and discuss next steps.</p><p>Shared decision-making means understanding the reasoning behind recommendations, alternatives when available, and potential benefits and risks.</p><h2>After your visit</h2><p>Your plan may include medication, education, practical supports, therapy collaboration, and follow-up care based on your needs.</p>'+framework()+'</div></div></section>'
body+='<section class="soft section"><div class="wrap narrow"><h2>Questions before your first visit</h2>'+faq([('Is the free consultation my first evaluation?',CONSULT),('Will I need to send records?',RECORDS),('How are medication changes and refills handled?',MEDICATION),('What should I track between appointments?','Notes on sleep, symptoms, daily functioning, benefits, side effects, and questions can help guide your next conversation. Use the patient resources if you find them helpful.'),('What if I need urgent help?','Do not wait for your next appointment in an emergency. Call or text 988 for crisis support. For an immediate medical or safety emergency, call 911 or seek emergency care.')])+'</div></section><section class="section"><div class="wrap cards"><a class="card" href="/patient-resources/starting-point/"><h2>My Starting Point</h2><p>A whole-person reflection you can bring to your first appointment.</p><span class="text-link">Explore the worksheet →</span></a><a class="card" href="/learning/psychiatric-medication-management-treatment/"><h2>Get the most from treatment</h2><p>What to notice, track, and discuss as treatment progresses.</p><span class="text-link">Read the article →</span></a><a class="card" href="/fees-insurance/"><h2>Plan for costs</h2><p>Review participating insurance plans and self-pay information.</p><span class="text-link">Fees & insurance →</span></a></div></section>'+end_cta()
write('/first-visit/','What to Expect at Your First Psychiatric Visit','Prepare for a 60-minute psychiatric evaluation at Ischys. Learn what to bring, how records and refills work, and what to expect.',body)
