def rendered_blocks(key,resource=False):
 parts=[];toc=[]
 for i,block in enumerate(SOURCE[key]['blocks']):
  text=block['text'];typ=block['type']
  if text.startswith('QR CODE:'):
   # Replace QR placeholders with real public links, or portal landing page.
   lookup={'PATIENT PORTAL':('/portal/','Patient portal'),'ISCHYS LEARNING CENTER':('/learning/','Learning Center'),'USARA':REFS[1][::-1],'ARP':REFS[6][::-1],'SMART RECOVERY':REFS[2][::-1],'LOCAL MEETING RESOURCES':REFS[7][::-1],'FAMILY SUPPORT RESOURCES':REFS[3][::-1],'NAMI UTAH':REFS[5][::-1]}
   dest,label=lookup.get(text[8:].strip(),('/patient-resources/','Patient resources'))
   parts.append('<p>'+a(dest,label+' →')+'</p>');continue
  if typ=='h2':
   anchor='section-'+str(i);toc.append((anchor,text));parts.append('<h2 id="'+anchor+'">'+esc(text)+'</h2>')
  elif '_' in text:
   parts.append('<p class="exercise">'+esc(text)+'</p>')
  else:parts.append('<p>'+esc(text)+'</p>')
 return ''.join(parts),toc
